from pathlib import Path
import json, difflib, re

P=Path(__file__).resolve().parents[1]
q=P/'testing/dialogue-clarity-v1'
changes=[]
def edit(name,old,new,why):
    f=P/'game'/name;t=f.read_text(encoding='utf-8-sig')
    assert t.count(old)==1,(name,old,t.count(old))
    t=t.replace(old,new);f.write_text(t,encoding='utf-8')
    changes.append(dict(file=name,old=old,new=new,reason=why))
def pair(name,old,new,why):
    for a,b in zip(old,new):edit(name,a,b,why)

