f=P/'game/options.rpy';t=f.read_text(encoding='utf-8');assert '0.31.0-relationship-secrets' in t;f.write_text(t.replace('0.31.0-relationship-secrets','0.32.0-dialogue-clarity'),encoding='utf-8')
changed=sorted({x['file'] for x in changes}|{'options.rpy'})
for name in changed:
    old=(q/(name+'.before')).read_text(encoding='utf-8-sig');new=(P/'game'/name).read_text(encoding='utf-8-sig')
    def flow(t):return [l.strip() for l in t.splitlines() if l.strip().startswith(('$ remember(', '$ award_once(', 'if ', 'elif ', 'else:', 'call ', 'return','label ', 'menu:', '$ dating', '$ ending'))]
    assert flow(old)==flow(new),name+' flow changed'
    assert len(re.findall(r'^\s+".*":\s*$',old,re.M))==len(re.findall(r'^\s+".*":\s*$',new,re.M)),name+' choice count'
    (q/(name+'.diff')).write_text(''.join(difflib.unified_diff(old.splitlines(True),new.splitlines(True),fromfile=name+' before',tofile=name+' after')),encoding='utf-8')
(q/'edits.json').write_text(json.dumps(changes,ensure_ascii=False,indent=2),encoding='utf-8')
(q/'changed.json').write_text(json.dumps(changed,ensure_ascii=False,indent=2),encoding='utf-8')
print('Changed',len(changes),'text spans in',len(changed),'modules; choices and state flow retained.')
